for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:a[10+dr][8+dc]=3
orig=[row[:] for row in a]
vertical={}; horizontal={}
for r,c,color in centers:
 own={(r+dr,c+dc) for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]}
 for dr,dc,store in [(1,0,vertical),(-1,0,vertical),(0,1,horizontal),(0,-1,horizontal)]:
